{
  "intent": "在顺序记忆师关卡7中，玩家答对后先发出"答对"信号通知其他组件触发胜利反馈动效，再跳转到下一关卡",
  "asset_catalog": [],
  "commands": [
    {
      "id": "emit_signal_correct_answer",
      "type": "EMIT_SIGNAL",
      "parameters": {
        "signal": "答对",
        "data": ""
      }
    },
    {
      "id": "scene_redirect_next_level",
      "type": "SCENE_REDIRECT",
      "parameters": {
        "url": "scene/顺序记忆师.json",
        "levelIndex": 7
      }
    }
  ]
}

{
  "intent": "在小笼包派对关卡3-3的分支选择环节，先用SHOW_TEXT显示提示文案"你选择了哪种做法？"，再用UPDATE_TEXT将同一文本元素改写为对应选择的结果说明，实现分支反馈文案的切换。",
  "asset_catalog": [],
  "commands": [
    {
      "id": "branch-hint-show",
      "type": "SHOW_TEXT",
      "parameters": {
        "elementId": "branch-hint-text",
        "text": "你选择了哪种做法？",
        "position": {"x": 200, "y": 260},
        "style": {
          "fontSize": "28",
          "color": "#ffffff",
          "fill": "#ffffff",
          "stroke": "#000000",
          "strokeThickness": 2,
          "textAlign": "center",
          "maxWidth": "400",
          "dropShadow": false,
          "zIndex": 110,
          "dropShadowColor": "#000000",
          "dropShadowBlur": 0,
          "dropShadowAngle": 1.2,
          "dropShadowDistance": 2
        },
        "padding": 20,
        "blocking": false,
        "dismissOnContinue": true,
        "id": "branch-hint-show"
      }
    },
    {
      "id": "branch-hint-update",
      "type": "UPDATE_TEXT",
      "parameters": {
        "elementId": "branch-hint-text",
        "text": "正确！蒸制8分钟，小笼包皮薄馅足，香气四溢！"
      }
    }
  ]
}

{
  "intent": "在手疾眼快关卡1-2中，先用SHOW_TEXT在画面左上角创建"当前分类：水果"的状态提示文本元素，再通过UPDATE_TEXT将同一文本元素内容改写为"当前分类：蔬菜"，实现游戏过程中分类状态的同步更新。",
  "asset_catalog": [],
  "commands": [
    {
      "id": "status-text-show",
      "type": "SHOW_TEXT",
      "parameters": {
        "elementId": "status-label",
        "text": "当前分类：水果",
        "position": {"x": 30, "y": 20},
        "style": {
          "fontSize": "28",
          "color": "#ffffff",
          "stroke": "#000000",
          "strokeThickness": 2,
          "dropShadow": false,
          "dropShadowColor": "#000000",
          "dropShadowBlur": 0,
          "dropShadowAngle": 1.2,
          "dropShadowDistance": 2,
          "maxWidth": 300,
          "textAlign": "left",
          "zIndex": 50
        },
        "padding": 14,
        "blocking": false,
        "dismissOnContinue": true
      }
    },
    {
      "id": "status-text-update",
      "type": "UPDATE_TEXT",
      "parameters": {
        "elementId": "status-label",
        "text": "当前分类：蔬菜"
      }
    }
  ]
}

{
  "intent": "在"关卡3-2"农具速记场景中，先显示时钟组件图片作为计时器，再通过设置缩放与透明度样式，突出倒计时的节拍视觉节奏",
  "asset_catalog": [
    {
      "id": "_____7",
      "type": "image",
      "path": "images/old/时钟组件.png",
      "origin": "existing",
      "exists": true,
      "metadata": {"status": "ready", "role": "计时器组件图片"}
    },
    {
      "id": "___4",
      "type": "animation",
      "path": "animations/基础效果/淡入.json",
      "origin": "existing",
      "exists": true,
      "metadata": {"status": "ready", "role": "入场淡入动画"}
    },
    {
      "id": "___5",
      "type": "animation",
      "path": "animations/基础效果/呼吸.json",
      "origin": "existing",
      "exists": true,
      "metadata": {"status": "ready", "role": "循环呼吸节拍动画"}
    }
  ],
  "commands": [
    {
      "id": "show_timer_clock",
      "type": "SHOW_IMAGE",
      "parameters": {
        "elementId": "timer-clock",
        "resourceId": "_____7",
        "position": {"x": 640, "y": 36},
        "size": {"width": 100, "height": 100},
        "visible": true,
        "zIndex": 10,
        "animation": {
          "entry": {"animId": "___4"},
          "loop": {"animId": "___5"}
        }
      }
    },
    {
      "id": "style_timer_clock",
      "type": "SET_ELEMENT_STYLE",
      "parameters": {
        "elementId": "timer-clock",
        "style": {
          "scale": 1.2,
          "alpha": 0.9
        }
      }
    }
  ]
}
